CREATE TABLE signal_adaptive_sessions(id uuid PRIMARY KEY,user_id integer NOT NULL REFERENCES signal_users(id),parent_id uuid UNIQUE REFERENCES signal_adaptive_sessions(id),procedure text NOT NULL,skill_id text NOT NULL,level text NOT NULL,bank_release_hash text NOT NULL REFERENCES signal_skill_bank_releases(content_hash),seed text NOT NULL,topics text[] NOT NULL,pool jsonb NOT NULL,answers jsonb NOT NULL DEFAULT '[]',revision integer NOT NULL DEFAULT 1,current_item_id text,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','finished','refined')),outcome text,created_at timestamptz NOT NULL DEFAULT now(),deadline timestamptz NOT NULL);
CREATE TABLE signal_adaptive_exposures(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES signal_adaptive_sessions(id),user_id integer NOT NULL REFERENCES signal_users(id),family_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX signal_adaptive_exposure_owner ON signal_adaptive_exposures(user_id,family_id);
CREATE FUNCTION signal_adaptive_preserve_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.pool IS DISTINCT FROM OLD.pool OR NEW.seed IS DISTINCT FROM OLD.seed OR NEW.procedure IS DISTINCT FROM OLD.procedure OR NEW.bank_release_hash IS DISTINCT FROM OLD.bank_release_hash OR NEW.deadline IS DISTINCT FROM OLD.deadline OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.parent_id IS DISTINCT FROM OLD.parent_id OR NEW.topics IS DISTINCT FROM OLD.topics THEN RAISE EXCEPTION 'adaptive source and deadline are immutable'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.answers) old_answer WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.answers) new_answer WHERE old_answer->>'commandKey'=new_answer->>'commandKey' AND old_answer->>'answer'=new_answer->>'answer' AND old_answer->>'receivedAt'=new_answer->>'receivedAt' AND old_answer->>'itemId'=new_answer->>'itemId')) THEN RAISE EXCEPTION 'original adaptive answers are immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER signal_adaptive_immutable BEFORE UPDATE ON signal_adaptive_sessions FOR EACH ROW EXECUTE FUNCTION signal_adaptive_preserve_source();
